// Unit tests for tls_certificate_verify_sign_with_k from
// src/tls/handshake/certificate_verify/sign_with_k.S (RFC 8446 §4.4.3)
//
// Vectors: (transcript_hash, k) -> (r,s), computed by a plain Python
// transliteration of the ECDSA signing equations against this
// repo's own embedded private key (tls_priv_key, src/tls/cert_data.S)
// and the real RFC 8446 §4.4.3 Content construction, then independently
// cross-checked by DER-encoding (r,s) and verifying it with Python's
// `cryptography` library (OpenSSL) against the server's real public
// key -- so both r/s correctness AND real-world interoperability are
// covered, the same discipline as test_p256_ecdsa/sign.c.

#include "test_harness.h"

extern int64_t tls_certificate_verify_sign_with_k(uint8_t sig_r[32], uint8_t sig_s[32],
                                                    const uint8_t transcript_hash[32],
                                                    const uint8_t k[32])
    __asm__("tls_certificate_verify_sign_with_k");
extern int64_t p256_ecdsa_verify(const uint8_t hash[32], const uint8_t sig_r[32],
                                  const uint8_t sig_s[32], const uint8_t qx[32],
                                  const uint8_t qy[32])
    __asm__("p256_ecdsa_verify");
extern void tls_certificate_verify_content_hash(uint8_t out[32], const uint8_t transcript_hash[32])
    __asm__("tls_certificate_verify_content_hash");

