static void test_sign(void) {
    TEST_SUITE("tls_certificate_verify_sign_with_k — matches reference r,s");
    for (int i = 0; i < NSIGN; i++) {
        uint8_t r[32], s[32];
        int64_t status = tls_certificate_verify_sign_with_k(r, s, SIGNS[i].transcript_hash, SIGNS[i].k);
        ASSERT_EQ("status == 0", 0, status);
        ASSERT_EQ("r matches", 0, memcmp(r, SIGNS[i].r, 32));
        ASSERT_EQ("s matches", 0, memcmp(s, SIGNS[i].s, 32));
    }
}

static void test_sign_verify_roundtrip(void) {
    TEST_SUITE("tls_certificate_verify_sign_with_k output verifies against the server's real pubkey");
    for (int i = 0; i < NSIGN; i++) {
        uint8_t r[32], s[32], digest[32];
        tls_certificate_verify_sign_with_k(r, s, SIGNS[i].transcript_hash, SIGNS[i].k);
        tls_certificate_verify_content_hash(digest, SIGNS[i].transcript_hash);
        int64_t ok = p256_ecdsa_verify(digest, r, s, SERVER_QX, SERVER_QY);
        ASSERT_EQ("signature verifies against the server pubkey", 1, ok);
    }
}

int main(void) {
    test_sign();
    test_sign_verify_roundtrip();
    test_summary();
    return 0;
}
